package com.mavric.health.audit;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;
import org.springframework.security.core.context.SecurityContextHolder;
import com.mavric.health.identity.*;
import com.mavric.health.tenancy.TenantRef;
import com.mavric.health.shared.*;
import com.mavric.health.persistence.sqlserver.SqlServerAuditStore;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
/** Service/authority boundary only: no DB, HTTP server or real permission claims. */
class AuditServiceSqlServerTest {
 static final String ID="aa000000-0000-4000-8000-000000000001",TENANT="bb000000-0000-4000-8000-000000000001";
 final Access access=mock(Access.class);final Sql sql=mock(Sql.class);final SqlServerAuditStore store=mock(SqlServerAuditStore.class);final AuditService service=new AuditService(store,access);final MockHttpServletRequest request=new MockHttpServletRequest("GET","/api/trace");
 void actor(String role,boolean tenant){var actor=new Actor(ID,"Synthetic","qa@example.test",tenant?TENANT:null,List.of(role),"a".repeat(64));when(access.actor()).thenReturn(actor);request.setAttribute("health.actor",actor);if(tenant)request.setAttribute("health.tenant",new TenantRef(TENANT,"Synthetic","clinic","CLINIC","HUMAN","ACTIVE",List.of()));else request.removeAttribute("health.tenant");TraceContext.REQUEST.set(request);}
 @AfterEach void cleanup(){TraceContext.REQUEST.remove();SecurityContextHolder.clearContext();}
 @Test void fourMethodsForwardExactRequestAndArgumentsWithoutLegacy(){actor("ADM",true);when(store.list(request,5)).thenReturn(List.of());when(store.events(request,"Query",null,null,null,null,null,9,5)).thenReturn(Map.of("items",List.of()));when(store.requests(request,5,401,"Query")).thenReturn(List.of());when(store.journey(request,ID)).thenReturn(Map.of("steps",List.of()));assertEquals(List.of(),service.list(5));assertEquals(Map.of("items",List.of()),service.events("Query",null,null,null,null,null,9,5));assertEquals(List.of(),service.requests(5,401,"Query"));assertEquals(Map.of("steps",List.of()),service.journey(ID));verify(store).list(request,5);verify(store).events(request,"Query",null,null,null,null,null,9,5);verify(store).requests(request,5,401,"Query");verify(store).journey(request,ID);verifyNoInteractions(sql);}
 @Test void authorityMatrixAndListTenantOnly(){for(String role:List.of("SAD","SOP","ADM","AUD","PRO"))for(boolean tenant:List.of(false,true)){reset(store);actor(role,tenant);boolean permitted=tenant?List.of("ADM","AUD").contains(role):List.of("SAD","SOP").contains(role);if(permitted){service.events(null,null,null,null,null,null,0,10);verify(store).events(request,null,null,null,null,null,null,0,10);}else{assertEquals(403,assertThrows(ApiException.class,()->service.events(null,null,null,null,null,null,0,10)).status);verifyNoInteractions(store);}reset(store);if(tenant&&permitted){service.list(10);verify(store).list(request,10);}else{assertEquals(403,assertThrows(ApiException.class,()->service.list(10)).status);verifyNoInteractions(store);}}}
 @Test void missingActor401MissingRequest500MalformedHost500Mismatch403(){when(access.actor()).thenThrow(new ApiException(401,"UNAUTHENTICATED","Safe"));assertEquals(401,assertThrows(ApiException.class,()->service.list(1)).status);reset(access);actor("AUD",true);TraceContext.REQUEST.remove();assertEquals(500,assertThrows(ApiException.class,()->service.list(1)).status);TraceContext.REQUEST.set(request);request.setAttribute("health.tenant","forged");assertEquals(500,assertThrows(ApiException.class,()->service.list(1)).status);actor("AUD",true);request.removeAttribute("health.actor");assertEquals(403,assertThrows(ApiException.class,()->service.list(1)).status);actor("AUD",true);request.removeAttribute("health.tenant");assertEquals(403,assertThrows(ApiException.class,()->service.list(1)).status);verifyNoInteractions(store);}
 @Test void noClientAuthorityOrFallbackOnStoreError(){actor("AUD",true);request.addHeader("X-Roles","SAD");request.addParameter("tenantId","forged");request.setContent("forged body".getBytes());var error=new ApiException(500,"DATABASE_ERROR","Safe");when(store.requests(request,1,0,null)).thenThrow(error);assertSame(error,assertThrows(ApiException.class,()->service.requests(1,0,null)));verify(store,times(1)).requests(request,1,0,null);verifyNoInteractions(sql);}
 @Test void legacyKeepsSqlAndMinimalSpringSelectsAutowired(){when(sql.rows(anyString(),any(Object[].class))).thenReturn(List.of());when(access.tenantId()).thenReturn(TENANT);try(var context=new AnnotationConfigApplicationContext()){context.registerBean(Sql.class,()->sql);context.registerBean(Access.class,()->access);context.registerBean(AuditService.class);context.refresh();assertEquals(List.of(),context.getBean(AuditService.class).list(5));verify(access).roles("ADM","AUD");verify(sql).rows(anyString(),eq(TENANT),eq(5));assertEquals(0,context.getBeanNamesForType(SqlServerAuditStore.class).length);assertEquals(0,context.getBeanNamesForType(javax.sql.DataSource.class).length);}verifyNoInteractions(store);}
}
